use std::fs
use std::collections::HashMap

fn num(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn getb(acc: HashMap<string, int>, name: string) -> int {
    match acc.get(name) {
        Some(v) => v,
        None => 0,
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 { continue }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let name = p[1]
            let amt = num(p[2])
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(name) {
                println("error: duplicate account")
            } else {
                acc.insert(name, amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let name = p[1]
            let amt = num(p[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                let bal = getb(acc, name)
                if cmd == "deposit" {
                    acc.insert(name, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let from = p[1]
            let to = p[2]
            let amt = num(p[3])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(from) {
                println("error: unknown account ${from}")
            } else if !acc.contains_key(to) {
                println("error: unknown account ${to}")
            } else if from == to {
                println("error: same account")
            } else {
                let fb = getb(acc, from)
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    let tb = getb(acc, to)
                    acc.insert(from, fb - amt)
                    acc.insert(to, tb + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            let name = p[1]
            if !acc.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                println("${getb(acc, name)}")
            }
        }
    }
    let mut names: Vec<string> = []
    for k in acc.keys() { names.push(k) }
    names.sort()
    for n in names {
        println("${n} ${getb(acc, n)}")
    }
}

